import json

baseline = json.load(open('baseline-packages.json'))
after = json.load(open('after-cpm-packages.json'))

def extract(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-2]
        for fw in proj['frameworks']:
            for pkg in fw['topLevelPackages']:
                result[(name, pkg['id'])] = pkg['resolvedVersion']
    return result

b = extract(baseline)
a = extract(after)

changes = []
unchanged = []
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(key, 'N/A')
    av = a.get(key, 'N/A')
    if bv != av:
        changes.append((key[0], key[1], bv, av))
    else:
        unchanged.append((key[0], key[1], bv))

print('CHANGES:')
for c in changes:
    print(f'  {c[0]:10s} {c[1]:40s} {c[2]:10s} -> {c[3]}')
print(f'UNCHANGED: {len(unchanged)} packages')
"

